constexpr double pi=3.14159265358979323846;
std::size_t checks{};
void check(bool value,const char* label){++checks;if(!value)throw std::runtime_error(label);}
void near(double a,double b,double tolerance,const char* label){check(std::abs(a-b)<=tolerance,label);}
void rejects(const std::function<void()>& f,const char* label){bool threw=false;try{f();}catch(const std::exception&){threw=true;}check(threw,label);}
CubicBezier line(Vec3 a,Vec3 b){const Vec3 v{(b.x-a.x)/3,(b.y-a.y)/3,(b.z-a.z)/3};return {{a,{a.x+v.x,a.y+v.y,a.z+v.z},{a.x+2*v.x,a.y+2*v.y,a.z+2*v.z},b}};}
CubicBezier quarter(double radius){const double k=4*(std::sqrt(2.0)-1)/3;CubicBezier c;c.control={Vec3{radius,0,0},Vec3{radius,k*radius,0},Vec3{k*radius,radius,0},Vec3{0,radius,0}};return c;}
std::vector<CubicBezier> circle(double radius){const auto first=quarter(radius);std::vector<CubicBezier> result{first};for(int part=1;part<4;++part){CubicBezier next;for(std::size_t i=0;i<4;++i){const auto v=first.control[i];next.control[i]=part==1?Vec3{-v.y,v.x,0}:part==2?Vec3{-v.x,-v.y,0}:Vec3{v.y,-v.x,0};}result.push_back(next);}return result;}
Mesh box(double x0,double y0,double z0,double x1,double y1,double z1){Mesh m;m.vertices={{x0,y0,z0},{x1,y0,z0},{x1,y1,z0},{x0,y1,z0},{x0,y0,z1},{x1,y0,z1},{x1,y1,z1},{x0,y1,z1}};m.triangles={{{0,2,1}},{{0,3,2}},{{4,5,6}},{{4,6,7}},{{0,1,5}},{{0,5,4}},{{1,2,6}},{{1,6,5}},{{2,3,7}},{{2,7,6}},{{3,0,4}},{{3,4,7}}};return m;}
Asset car(double width=1800,double length=4000,double height=1500){Asset a;a.id=101;a.name="Arbitrary selected source";a.mesh=box(-length/2,-width/2,0,length/2,width/2,height);a.anchor={-500,0,0};a.allowed_yaws_degrees={0};a.category=AssetCategory::Book;a.allowed_furniture=furniture_bit(FurnitureCategory::KitchenCounter);return prepare_asset(std::move(a));}
ArrangeSettings settings(){ArrangeSettings s;s.seed=413032;s.spacing_mm=0;s.edge_clearance_mm=0;s.cluster_strength=0;return s;}
// Independent Simpson integration of the derivative polynomial. This is not
// the production chord table or its projection inversion.
double reference_length(const CubicBezier& c,double end=1){
    const auto& p=c.control;const auto speed=[&](double t){const double u=1-t;const double x=3*u*u*(p[1].x-p[0].x)+6*u*t*(p[2].x-p[1].x)+3*t*t*(p[3].x-p[2].x);const double y=3*u*u*(p[1].y-p[0].y)+6*u*t*(p[2].y-p[1].y)+3*t*t*(p[3].y-p[2].y);const double z=3*u*u*(p[1].z-p[0].z)+6*u*t*(p[2].z-p[1].z)+3*t*t*(p[3].z-p[2].z);return std::sqrt(x*x+y*y+z*z);};
    constexpr int count=20000;const double step=end/count;double sum=speed(0)+speed(end);for(int i=1;i<count;++i)sum+=(i%2?4:2)*speed(i*step);return sum*step/3;
}
bool same(const Placement& a,const Placement& b){return a.stable_id==b.stable_id&&a.asset_id==b.asset_id&&a.region_id==b.region_id&&a.position.x==b.position.x&&a.position.y==b.position.y&&a.position.z==b.position.z&&a.yaw_degrees==b.yaw_degrees&&a.scale==b.scale&&a.locked==b.locked;}
void sampling_and_nonuniform_parameter(){
    CubicBezier cubic;cubic.control={Vec3{0,0,0},Vec3{0,0,0},Vec3{0,0,0},Vec3{1000,0,0}};
    const std::array<CubicBezier,1> curves{cubic};const auto path=PathCurve::build(curves);
    near(path.length_mm(),1000,1e-9,"Straight path world length");const auto middle=path.at(500);near(middle.position.x,500,1e-8,"Arc inversion fixes nonuniform parameter speed on a straight cubic");check(std::abs(middle.parameter-.5)>.2,"Half distance is not blindly half parameter");
    near(path.at(0).position.x,0,1e-9,"Open start");near(path.at(1000).position.x,1000,1e-9,"Open end");near(middle.left.x,0,1e-9,"Straight left X");near(middle.left.y,1,1e-9,"Straight left Y");
    rejects([&]{path.at(-1);},"Open path rejects negative distance");rejects([&]{path.at(1001);},"Open path rejects overflow distance");rejects([&]{path.at(1,5);},"Arc inversion honors its work allowance");
}
void curved_world_metric(){
    auto source=quarter(10000);for(auto& p:source.control){p.x=2*p.x+45000;p.y=.5*p.y-25000;p.z=.3*p.x;}
    const std::array<CubicBezier,1> curves{source};PathBuildSettings precise;precise.length_tolerance_mm=.1;const auto path=PathCurve::build(curves,false,precise);const auto stats=path.diagnostics();const double exact=reference_length(source);
    check(path.length_mm()<=exact+.0001,"Chord arc length is a lower bound on an independently integrated world curve");check(exact<=path.length_mm()+stats.length_error_bound_mm+.0001,"Control polygon bounds contain independent integral");check(stats.length_error_bound_mm<=.1&&stats.maximum_deviation_bound_mm<=.1,"All admitted curve errors honor requested bounds");
    for(double fraction:{.1,.25,.5,.75,.9}){const auto f=path.at(path.length_mm()*fraction);near(reference_length(source,f.parameter),f.distance_mm,.101,"World arc inversion independently agrees with Simpson integration");near(f.tangent.x*f.left.x+f.tangent.y*f.left.y,0,1e-9,"Lateral vector is perpendicular to the local heading");near(std::hypot(f.left.x,f.left.y),1,1e-9,"Horizontal lateral vector stays normalized");}
    check(std::abs(path.at(path.length_mm()*.1).left.x-path.at(path.length_mm()*.9).left.x)>.2,"Curved sideways direction is not a fixed world-axis offset");
}
void complete_lane_footprint_and_hole(){
    const std::vector<CubicBezier> square{line({0,0,0},{10000,0,0}),line({10000,0,0},{10000,10000,0}),line({10000,10000,0},{0,10000,0}),line({0,10000,0},{0,0,0})};const auto path=PathCurve::build(square,true);PathLane lane;lane.width_mm=3000;const auto mask=PathLaneMask::build(path,lane);
    for(const auto p:std::array<Vec3,4>{{{1000,1000,10},{9000,1000,10},{9000,9000,10},{1000,9000,10}}})check(mask.validate({p,{1,1,1},0},0).reason==Rejection::None,"Each rectangle corner is inside the permitted closed lane");
    check(mask.validate({{5000,5000,10},{4000,4000,1},0},0).reason==Rejection::Boundary,"Complete rectangle rejects an enclosed hole despite all corners being inside");
    check(mask.validate({{5000,0,10},{1000,300,10},0},0).reason==Rejection::None,"Whole footprint inside lane passes");check(mask.validate({{5000,1400,10},{1000,300,10},0},0).reason==Rejection::Boundary,"Center inside lane cannot authorize an overhanging footprint");
    check(mask.validate({{5000,0,10},{1000,1490,10},0},20).reason==Rejection::Boundary,"User edge margin applies to full footprint");
    near(path.at(path.length_mm()+2500).position.x,2500,1e-7,"Closed distance wraps without duplicating seam");near(path.at(-2500).position.y,2500,1e-7,"Negative closed distance wraps");
    PathLane too_wide;too_wide.width_mm=30000;rejects([&]{PathLaneMask::build(path,too_wide);},"Lane folding over a tight bend is rejected explicitly");
    const std::vector<CubicBezier> comb{line({0,0,0},{0,10000,0}),line({0,10000,0},{5000,10000,0}),line({5000,10000,0},{5000,0,0}),line({5000,0,0},{10000,0,0}),line({10000,0,0},{10000,10000,0})};
    const auto notched=PathCurve::build(comb);PathLane narrow;narrow.width_mm=1000;const auto notch=PathLaneMask::build(notched,narrow);
    for(double x:{0,10000})for(double y:{4900,5100})check(notch.validate({{x,y,10},{1,1,1},0},0).reason==Rejection::None,"Notched-lane rectangle corner lies inside");
    check(notch.validate({{5000,5000,10},{1,1,1},0},0).reason==Rejection::None,"Notched-lane rectangle center also lies inside");
    check(notch.validate({{5000,5000,10},{5000,100,1},0},0).reason==Rejection::Boundary,"Complete footprint rejects forbidden notches despite corners and center all inside");
}
void six_cars_two_directions(){
    const std::array<CubicBezier,1> c{line({0,0,0},{15000,0,0})};const auto curve=PathCurve::build(c);const std::array<PathLane,2> lanes{{{21,3,1750,3200,5000,false,true},{22,3,-1750,3200,5000,true,true}}};
    const std::vector<Asset> assets{car()};const std::vector<FurnitureBody> floor{{1,box(0,-4000,-20,15000,4000,0)}};QuerySettings q;q.require_front_access=false;FurniturePlacementQuery geometry(floor,q);
    const auto result=arrange_path({curve,lanes,assets,{},{},&geometry},settings(),{});
    check(result.result.stats.requested==6&&result.result.stats.accepted==6&&result.result.stats.underfilled==0,"Two-way lane totals are 3+3, not multiplied or category capped");check(result.accepted_per_lane[0]==3&&result.accepted_per_lane[1]==3,"Independent lane quantities");
    for(std::size_t i=0;i<6;++i){const auto& p=result.result.placements[i];const auto b=placement_bounds(assets[0],p);near(b.center.x,i<3?2500+5000*i:12500-5000*(i-3),.001,"Native base-center follows count distance even with authored off-center anchor");near(b.center.y,i<3?1750:-1750,.001,"Source-relative left/right offsets");near(b.center.z-b.half_extents.z,0,.001,"Base center rests on the real road");near(std::remainder(p.yaw_degrees,360),i<3?0:180,.00001,"Opposite travel orientation");check(b.center.x-b.half_extents.x>=0&&b.center.x+b.half_extents.x<=15000,"Complete car stays inside path caps");check(std::abs(b.center.y-(i<3?1750:-1750))+b.half_extents.y<1600,"Complete car stays inside its assigned lane width");}
}
void curved_jitter_scale_repeat(){
    const std::array<CubicBezier,1> c{quarter(50000)};const auto curve=PathCurve::build(c);const std::array<PathLane,2> lanes{{{1,3,2200,4000,5000,false,true},{2,3,-2200,4000,5000,true,true}}};const std::vector<Asset> assets{car()};auto s=settings();s.random_scale=true;s.scale_min=.8;s.scale_max=1.1;PathSettings path;path.lateral_jitter_mm=400;path.longitudinal_jitter_mm=500;
    const auto result=arrange_path({curve,lanes,assets},s,path),repeated=arrange_path({curve,lanes,assets},s,path);check(result.result.stats.accepted==6,"Curved two-way random placements fill six separated slots");check(result.locations.size()==6,"Each output retains its actual lane and distance");bool varied=false;
    for(std::size_t i=0;i<result.result.placements.size();++i){const auto& p=result.result.placements[i];check(same(p,repeated.result.placements[i]),"Same seed repeats exact curve poses, scales and IDs");check(p.scale>=.8&&p.scale<=1.1,"Random scale obeys visible range");if(std::abs(p.scale-result.result.placements[0].scale)>.01)varied=true;const auto& loc=result.locations[i];const std::size_t lane=p.region_id-1;check(std::abs(loc.lateral_mm-lanes[lane].offset_mm)<=400,"Lateral jitter stays inside authored spread");const auto f=curve.at(loc.distance_mm);const auto b=placement_bounds(assets[0],p);near((b.center.x-f.position.x)*f.tangent.x+(b.center.y-f.position.y)*f.tangent.y,0,.001,"Offset is sideways in curve-local coordinates");near((b.center.x-f.position.x)*f.left.x+(b.center.y-f.position.y)*f.left.y,loc.lateral_mm,.001,"Actual base center carries the sampled local offset");
        const double r=p.yaw_degrees*pi/180,cs=std::cos(r),sn=std::sin(r);const double ox=-b.center.x*cs-b.center.y*sn,oy=b.center.x*sn-b.center.y*cs;const double closestX=std::clamp(ox,-b.half_extents.x,b.half_extents.x),closestY=std::clamp(oy,-b.half_extents.y,b.half_extents.y);const double closestRadius=std::hypot(b.center.x+closestX*cs-closestY*sn,b.center.y+closestX*sn+closestY*cs);const double centerRadius=50000-lanes[lane].offset_mm;check(closestRadius>centerRadius-2000-.2,"Entire car clears independent inner circular boundary");for(double x:{-b.half_extents.x,b.half_extents.x})for(double y:{-b.half_extents.y,b.half_extents.y})check(std::hypot(b.center.x+x*cs-y*sn,b.center.y+x*sn+y*cs)<centerRadius+2000+20,"Entire car clears independent outer circular boundary");
    }
    check(varied,"Random scale actually varies");++s.seed;const auto different=arrange_path({curve,lanes,assets},s,path);check(!same(result.result.placements[0],different.result.placements[0]),"New seed changes path variation");near(assets[0].bounds.max.z,1500,1e-9,"Source remains full size");
}
